// ratelimit_test.go
package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.t
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.t = c.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clk := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 1, 1, nil, true},
		{"zero capacity", 0, 1, clk, true},
		{"negative capacity", -1, 1, clk, true},
		{"zero rate", 1, 0, clk, true},
		{"negative rate", 1, -1, clk, true},
		{"NaN rate", 1, nan(), clk, true},
		{"valid", 5, 2.5, clk, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if tc.wantErr && err == nil {
				t.Fatal("expected error")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	cases := []struct {
		name   string
		cap    int
		rate   float64
		steps  []step
		expect []bool
	}{
		{
			name: "burst then empty",
			cap:  5, rate: 1,
			steps:  []step{{0, 5}, {0, 1}},
			expect: []bool{true, false},
		},
		{
			name: "refill over time",
			cap:  2, rate: 2,
			steps:  []step{{0, 2}, {500 * time.Millisecond, 1}, {0, 1}},
			expect: []bool{true, true, false},
		},
		{
			name: "n larger than capacity",
			cap:  2, rate: 10,
			steps:  []step{{0, 3}},
			expect: []bool{false},
		},
		{
			name: "nonpositive n",
			cap:  1, rate: 1,
			steps:  []step{{0, 0}, {0, -2}},
			expect: []bool{true, true},
		},
		{
			name: "fractional refill",
			cap:  1, rate: 10,
			steps:  []step{{0, 1}, {100 * time.Millisecond, 1}},
			expect: []bool{true, true},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clk := newFakeClock()
			b, err := New(tc.cap, tc.rate, clk)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tc.steps {
				clk.Advance(s.advance)
				if got := b.AllowN(s.n); got != tc.expect[i] {
					t.Fatalf("step %d: got %v, want %v", i, got, tc.expect[i])
				}
			}
		})
	}
}

type step struct {
	advance time.Duration
	n       int
}

func TestConcurrentAllowN(t *testing.T) {
	clk := newFakeClock()
	b, err := New(100, 1000, clk)
	if err != nil {
		t.Fatal(err)
	}
	var wg sync.WaitGroup
	var mu sync.Mutex
	allowed := 0
	for i := 0; i < 50; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed > 100 {
		t.Fatalf("allowed %d tokens, exceeds capacity", allowed)
	}
}

func nan() float64 { return 0.0 / 1.0 * (1.0 / 0.0) }
